            }
          ]
        },
        "bodySite": {
          "text": "Right heel"
        },
        "note": [
          {
            "text": "Known diagnosis from a consultation approximately 3/52 ago; ongoing and stable. No features suggesting Achilles tendinopathy, stress fracture, inflammatory arthropathy or a neuropathic cause."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-3",
