          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Mild pes planus"
        },
        "note": [
          {
            "text": "Mildly reduced arches on examination, consistent with pes planus; identified as a risk factor for plantar fasciitis."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-4",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-4",
