          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "differential"
            }
          ]
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-6",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-6",
        "subject": {
          "reference": "Patient/patient-1"
        },
        "code": {
          "text": "Bacterial pharyngitis considered less likely in the differential diagnosis"
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "differential"
            }
          ]
        },
        "note": [
          {
            "text": "Less likely given the examination."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Reported fever"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Feeling a bit feverish for the last few days; onset documented as 3/7. Fluctuating low-grade fevers mainly in the evenings. Patient thinks the temperature may have reached about 38, but this was uncertain and not a documented measurement."
      }
    },
