        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Patient-reported home thermometer reading"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 37.8
        },
        "note": [
          {
            "text": "Checked once yesterday on a home thermometer; unit not explicitly stated."
          }
        ]
      }
    },
