        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Sore throat"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild scratchy sore throat for 2/7."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Cough"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Dry cough for 2/7; denies chronic cough."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Constitutional symptoms and appetite"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Some generalised myalgias and fatigue; feels a bit crook and wiped. Appetite slightly decreased, but still eating solids and drinking fluids. No rigors or confusion."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
